CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_pose text NOT NULL DEFAULT 'thumbs-up');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_select ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() = id);
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE FUNCTION public.create_student_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, left(coalesce(NEW.raw_user_meta_data->>'display_name', ''),80)); RETURN NEW; END; $$;
CREATE TRIGGER student_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_student_profile();
CREATE TABLE public.learning_progress (user_id uuid NOT NULL, item_id text NOT NULL, kind text NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,item_id,kind), CONSTRAINT learning_kind CHECK(kind IN ('topic','practice','project')));
GRANT SELECT, INSERT, DELETE ON public.learning_progress TO authenticated;
GRANT ALL ON public.learning_progress TO service_role;
ALTER TABLE public.learning_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_select ON public.learning_progress FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY progress_insert ON public.learning_progress FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY progress_delete ON public.learning_progress FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE TABLE public.mentor_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'New learning conversation', topic_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.mentor_threads TO authenticated;
GRANT ALL ON public.mentor_threads TO service_role;
ALTER TABLE public.mentor_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY threads_owner ON public.mentor_threads FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE INDEX mentor_threads_user ON public.mentor_threads(user_id,updated_at DESC);
CREATE TABLE public.mentor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.mentor_threads(id) ON DELETE CASCADE, sdk_id text NOT NULL, message jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,sdk_id));
GRANT SELECT, INSERT ON public.mentor_messages TO authenticated;
GRANT ALL ON public.mentor_messages TO service_role;
ALTER TABLE public.mentor_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_read ON public.mentor_messages FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.mentor_threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE POLICY messages_write ON public.mentor_messages FOR INSERT TO authenticated WITH CHECK (EXISTS(SELECT 1 FROM public.mentor_threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE INDEX mentor_messages_order ON public.mentor_messages(thread_id,created_at);
CREATE TABLE public.mentor_gateway_state (id boolean PRIMARY KEY DEFAULT true, paused boolean NOT NULL DEFAULT false, reason text, status integer, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.mentor_gateway_state TO service_role;
ALTER TABLE public.mentor_gateway_state ENABLE ROW LEVEL SECURITY;